export function PresenterPage(){const [chapter,setChapter]=useState(0);const navigate=useNavigate();const current=chapters[chapter];return <div className="presenter"><div className="presenter-progress">{chapters.map((c,i)=><button key={c.title} className={i===chapter?'active':i<chapter?'done':''} onClick={()=>setChapter(i)}><span>{i+1}</span><small>{c.title}</small></button>)}</div><div className="presenter-stage"><span className="eyebrow">Chapter {chapter+1} of {chapters.length}</span><h1>{current.title}</h1><p>{current.caption}</p><button className="primary-button large" onClick={()=>navigate(current.url)}>Open this view <ArrowRight/></button><div className="presenter-preview">{chapter===0&&<SystemGraph compact/>}{chapter===1&&<div className="preview-path">{['Trade accepted','Validated','Enriched','Journaled','Warehouse load','Exposure report'].map((x,i)=><span key={x} className={i===4?'failed':''}>{i===4?<XCircle/>:<Check/>}{x}</span>)}</div>}{chapter===2&&<div className="preview-compare"><strong>UAT</strong><span>ETL 2.4.1</span><span>synthetic reference data</span><span className="failed">warehouse route absent</span><strong>Production</strong><span>ETL 2.3.8</span><span>authoritative reference data</span><span>warehouse route present</span></div>}{chapter===3&&<div className="preview-orbit"><code>POST /trades</code><span>4 services</span><span>6 scenarios</span><span>3 tables</span><span className="failed">1 evidence gap</span></div>}{chapter===4&&<div className="preview-autopsy"><TriangleAlert/><strong>legacy-netting-mode</strong><span>3 environments</span><span>0 current manifest references</span><small>Unknown: unharvested operational scripts</small></div>}{chapter===5&&<pre>{`atlas://requirements/req-exposure
→ evidence references
→ stable portal links
→ explicit unknowns`}</pre>}</div></div><div className="presenter-controls"><button className="secondary-button" onClick={()=>navigate('/')}><XCircle/> Exit</button><button disabled={chapter===0} onClick={()=>setChapter(x=>x-1)}>Back</button><button onClick={()=>setChapter(0)}><RotateCcw/> Restart</button><button className="primary-button" disabled={chapter===chapters.length-1} onClick={()=>setChapter(x=>x+1)}>Next <ArrowRight/></button></div></div>}

export function NotFoundPage(){return <div className="page"><div className="not-found"><span className="eyebrow">404</span><h1>This atlas route does not exist</h1><p>The link may reference evidence that was not included in this demo dataset.</p><Link className="primary-button" to="/">Return to overview</Link></div></div>}
